from dataclasses import dataclass, field
from typing import ClassVar


@dataclass
class InventoyItem:
    name: str
    unit_price: float
    item_tags: list[str] = field(default_factory=list)
    class_var: ClassVar[int] = 100
    # class var.. wont be in __init


# we can look up code generated by the. decorator by calling help

help(InventoyItem)

# Inheritence senarios
# when inhereting from a class thats not dataclass
# use __post_init to call base call __init method


class Rectangle:
    def __init__(self, l: int, b: int) -> None:
        self.l = l
        self.b = b


@dataclass
class Square(Rectangle):
    side: int

    def __post_init__(self):
        super().__init__(self.side, self.side)


# When base class uses dataclass


@dataclass
class Rect:
    length: int
    b: int


@dataclass
class ColoredRect(Rect):
    color: str


# we can pass all properties starting from base to lowest
c: ColoredRect = ColoredRect(3, 5, "Red")
